-- Customer Behavior Analysis: SQL queries (MySQL)
-- Table 'customers' is created by the Python script (cleaned data loaded with pandas to_sql)

USE cust_shopping_behavior;

-- Q1. What is the total revenue generated by male vs. female customers?
SELECT gender, SUM(purchase_amount) AS total_revenue
FROM customers
GROUP BY gender;

-- Q2. Which customers used a discount but still spent more than the average purchase amount?
SELECT customer_id, purchase_amount
FROM customers
WHERE discount_applied = 'Yes'
  AND purchase_amount > (SELECT AVG(purchase_amount) FROM customers);

-- Q3. Which are the top 5 products with the highest average review rating?
SELECT item_purchased AS products, ROUND(AVG(review_rating), 2) AS avg_rew
FROM customers
GROUP BY products
ORDER BY avg_rew DESC
LIMIT 5;

-- Q4. Compare the average purchase amount between Standard and Express shipping.
SELECT shipping_type, ROUND(AVG(purchase_amount), 3) AS avg_pur_amt
FROM customers
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type;

-- Q5. Do subscribed customers spend more? Compare average spend and total revenue.
SELECT subscription_status,
       COUNT(customer_id) AS total_customers,
       SUM(purchase_amount) AS total_revenue,
       AVG(purchase_amount) AS avg_spend
FROM customers
GROUP BY subscription_status
ORDER BY total_revenue, avg_spend DESC;

-- Q6. Which 5 products have the highest percentage of purchases with discount applied?
SELECT item_purchased,
       ROUND(100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) / COUNT(*), 2) AS discount_rate
FROM customers
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;

-- Q7. Segment customers into New, Returning and Loyal and show the count of each segment.
WITH customer_type AS (
    SELECT customer_id, previous_purchases,
           CASE
               WHEN previous_purchases = 1 THEN 'new'
               WHEN previous_purchases BETWEEN 2 AND 10 THEN 'returning'
               ELSE 'loyal'
           END AS customer_segment
    FROM customers
)
SELECT customer_segment, COUNT(*) AS num_of_customers
FROM customer_type
GROUP BY customer_segment;

-- Q8. What are the top 3 most purchased products in each category?
SELECT * FROM (
    SELECT category, item_purchased, COUNT(*) AS qty,
           RANK() OVER (PARTITION BY category ORDER BY COUNT(*) DESC) AS rnk
    FROM customers
    GROUP BY category, item_purchased
) t
WHERE rnk <= 3;

-- Q9. Are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT subscription_status, COUNT(customer_id) AS repeat_buyers
FROM customers
WHERE previous_purchases > 5
GROUP BY subscription_status;

-- Q10. What is the revenue contribution of each age group?
SELECT age_group, SUM(purchase_amount) AS total_revenue
FROM customers
GROUP BY age_group
ORDER BY total_revenue DESC;
